// Construye el prompt para el LLM local (D14 · Sub · IA).
const j = $input.first().json || {};
const origen = j.text || (j.recibido && j.recibido.text) || j.message || JSON.stringify(j);
const texto = String(origen).slice(0, 4000);
return [{ json: { prompt:
  'Resume en maximo 3 frases, en espanol y sin rodeos, el siguiente texto:\n\n' + texto
} }];

