// Normaliza la respuesta del LLM (o el fallo) al esquema del sub.
const j = $input.first().json || {};
if (j.response) {
  return [{ json: { ok: true, resumen: String(j.response).slice(0, 3000), model: j.model || '' } }];
}
return [{ json: {
  ok: false,
  error: String((j.error && j.error.message) || j.error || 'LLM no disponible').slice(0, 400),
} }];
